package com.stockflow.api; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*; @RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class}) ResponseEntity<?> business(RuntimeException e){return ResponseEntity.unprocessableEntity().body(Map.of("timestamp",Instant.now(),"code",e.getMessage(),"message","The request violates an inventory rule"));}}